`timescale 1ns / 1ps

// Passive-buzzer note player generated by tools/generate_buzzer_note_player.py.
// It follows the tutorial-style method: note table + beat table + square-wave
// divider. Background music is disabled in this build; win is a separated
// rising cue; fail is a separated descending cue.
module buzzer_note_player #(
    parameter int CLK_HZ       = 50_000_000,
    parameter int TEMPO_BPM    = 96,
    parameter int NOTE_GAP_MS  = 35,
    parameter bit BUZZER_ACTIVE_LOW = 1'b1,
    parameter int COLLISION_HZ = 1_000,
    parameter int COLLISION_MS = 150
) (
    input  logic       clk_i,
    input  logic       rst_i,
    input  logic       stop_i,
    input  logic       collision_start_i,
    input  logic       play_start_i,
    input  logic [1:0] play_song_i,
    input  logic       play_loop_i,
    output logic       busy_o,
    output logic       done_o,
    output logic       beep_o
);
    localparam logic [1:0] SONG_BACKGROUND = 2'd0;
    localparam logic [1:0] SONG_WIN        = 2'd1;
    localparam logic [1:0] SONG_FAIL       = 2'd2;

    // Divide before multiplying to avoid 32-bit int overflow at 50 MHz.
    localparam int UNIT_CYCLES = (CLK_HZ / (TEMPO_BPM * 4)) * 60;
    localparam int NOTE_GAP_CYCLES = (CLK_HZ / 1000) * NOTE_GAP_MS;
    localparam int COLLISION_CYCLES = (CLK_HZ / 1000) * COLLISION_MS;
    localparam int COLLISION_HALF_CYCLES = CLK_HZ / (COLLISION_HZ * 2);

    localparam logic [1:0] MODE_IDLE      = 2'd0;
    localparam logic [1:0] MODE_SONG      = 2'd1;
    localparam logic [1:0] MODE_COLLISION = 2'd2;

    localparam int NOTE_CODE_W = 5;
    localparam logic [NOTE_CODE_W-1:0] NOTE_REST = 0;
    localparam logic [NOTE_CODE_W-1:0] NOTE_E4 = 1;
    localparam logic [NOTE_CODE_W-1:0] NOTE_G4 = 2;
    localparam logic [NOTE_CODE_W-1:0] NOTE_A4 = 3;
    localparam logic [NOTE_CODE_W-1:0] NOTE_AS4 = 4;
    localparam logic [NOTE_CODE_W-1:0] NOTE_B4 = 5;
    localparam logic [NOTE_CODE_W-1:0] NOTE_C5 = 6;
    localparam logic [NOTE_CODE_W-1:0] NOTE_D5 = 7;
    localparam logic [NOTE_CODE_W-1:0] NOTE_E5 = 8;
    localparam logic [NOTE_CODE_W-1:0] NOTE_F5 = 9;
    localparam logic [NOTE_CODE_W-1:0] NOTE_G5 = 10;
    localparam logic [NOTE_CODE_W-1:0] NOTE_A5 = 11;
    localparam logic [NOTE_CODE_W-1:0] NOTE_L5 = 12;
    localparam logic [NOTE_CODE_W-1:0] NOTE_L6 = 13;
    localparam logic [NOTE_CODE_W-1:0] NOTE_L7 = 14;
    localparam logic [NOTE_CODE_W-1:0] NOTE_1 = 15;
    localparam logic [NOTE_CODE_W-1:0] NOTE_2 = 16;
    localparam logic [NOTE_CODE_W-1:0] NOTE_3 = 17;
    localparam logic [NOTE_CODE_W-1:0] NOTE_4 = 18;
    localparam logic [NOTE_CODE_W-1:0] NOTE_5 = 19;
    localparam logic [NOTE_CODE_W-1:0] NOTE_6 = 20;
    localparam logic [NOTE_CODE_W-1:0] NOTE_7 = 21;
    localparam logic [NOTE_CODE_W-1:0] NOTE_H1 = 22;
    localparam logic [NOTE_CODE_W-1:0] NOTE_H2 = 23;
    localparam logic [NOTE_CODE_W-1:0] NOTE_H3 = 24;
    localparam logic [NOTE_CODE_W-1:0] NOTE_H4 = 25;
    localparam logic [NOTE_CODE_W-1:0] NOTE_H5 = 26;

    localparam int BG_NOTE_COUNT   = 372;
    localparam int WIN_NOTE_COUNT  = 14;
    localparam int FAIL_NOTE_COUNT = 12;
    localparam int NOTE_INDEX_W    = 9;

    logic [1:0] active_song;
    logic       active_loop;
    logic [1:0] play_mode;
    logic       resume_song_after_collision;

    logic [NOTE_INDEX_W-1:0] note_index;
    logic [NOTE_CODE_W-1:0] current_note;
    logic [3:0] current_units;

    logic [31:0] duration_cnt;
    logic [31:0] tone_cnt;
    logic [31:0] collision_cnt;
    logic [31:0] collision_tone_cnt;
    logic        beep_raw;

    assign beep_o = BUZZER_ACTIVE_LOW ? ~beep_raw : beep_raw;

    function automatic int half_cycles_for_note(input logic [NOTE_CODE_W-1:0] note);
        begin
            unique case (note)
                NOTE_E4: half_cycles_for_note = CLK_HZ / (330 * 2);
                NOTE_G4: half_cycles_for_note = CLK_HZ / (392 * 2);
                NOTE_A4: half_cycles_for_note = CLK_HZ / (440 * 2);
                NOTE_AS4: half_cycles_for_note = CLK_HZ / (466 * 2);
                NOTE_B4: half_cycles_for_note = CLK_HZ / (494 * 2);
                NOTE_C5: half_cycles_for_note = CLK_HZ / (523 * 2);
                NOTE_D5: half_cycles_for_note = CLK_HZ / (587 * 2);
                NOTE_E5: half_cycles_for_note = CLK_HZ / (659 * 2);
                NOTE_F5: half_cycles_for_note = CLK_HZ / (698 * 2);
                NOTE_G5: half_cycles_for_note = CLK_HZ / (784 * 2);
                NOTE_A5: half_cycles_for_note = CLK_HZ / (880 * 2);
                NOTE_L5: half_cycles_for_note = CLK_HZ / (349 * 2);
                NOTE_L6: half_cycles_for_note = CLK_HZ / (392 * 2);
                NOTE_L7: half_cycles_for_note = CLK_HZ / (440 * 2);
                NOTE_1: half_cycles_for_note = CLK_HZ / (466 * 2);
                NOTE_2: half_cycles_for_note = CLK_HZ / (523 * 2);
                NOTE_3: half_cycles_for_note = CLK_HZ / (587 * 2);
                NOTE_4: half_cycles_for_note = CLK_HZ / (622 * 2);
                NOTE_5: half_cycles_for_note = CLK_HZ / (698 * 2);
                NOTE_6: half_cycles_for_note = CLK_HZ / (784 * 2);
                NOTE_7: half_cycles_for_note = CLK_HZ / (880 * 2);
                NOTE_H1: half_cycles_for_note = CLK_HZ / (932 * 2);
                NOTE_H2: half_cycles_for_note = CLK_HZ / (1047 * 2);
                NOTE_H3: half_cycles_for_note = CLK_HZ / (1175 * 2);
                NOTE_H4: half_cycles_for_note = CLK_HZ / (1245 * 2);
                NOTE_H5: half_cycles_for_note = CLK_HZ / (1397 * 2);
                default: half_cycles_for_note = 1;
            endcase
        end
    endfunction

    function automatic int duration_cycles(input logic [3:0] units);
        begin
            duration_cycles = UNIT_CYCLES * int'(units);
        end
    endfunction

    function automatic int sound_cycles(input logic [3:0] units);
        int total_cycles;
        begin
            total_cycles = duration_cycles(units);
            if (total_cycles > NOTE_GAP_CYCLES) begin
                sound_cycles = total_cycles - NOTE_GAP_CYCLES;
            end else begin
                sound_cycles = total_cycles;
            end
        end
    endfunction

