    function automatic logic [3:0] win_units(input int idx);
        begin
            unique case (idx)
                0: win_units = 2;
                1: win_units = 1;
                2: win_units = 2;
                3: win_units = 1;
                4: win_units = 2;
                5: win_units = 1;
                6: win_units = 2;
                7: win_units = 1;
                8: win_units = 2;
                9: win_units = 1;
                10: win_units = 2;
                11: win_units = 1;
                12: win_units = 4;
                13: win_units = 2;
                default: win_units = 1;
            endcase
        end
    endfunction

    function automatic logic [3:0] fail_units(input int idx);
        begin
            unique case (idx)
                0: fail_units = 2;
                1: fail_units = 1;
                2: fail_units = 2;
                3: fail_units = 1;
                4: fail_units = 2;
                5: fail_units = 1;
                6: fail_units = 3;
                7: fail_units = 1;
                8: fail_units = 3;
                9: fail_units = 1;
                10: fail_units = 5;
                11: fail_units = 2;
                default: fail_units = 1;
            endcase
        end
    endfunction

    function automatic int song_len(input logic [1:0] song);
        begin
            unique case (song)
                SONG_WIN:  song_len = WIN_NOTE_COUNT;
                SONG_FAIL: song_len = FAIL_NOTE_COUNT;
                default:   song_len = BG_NOTE_COUNT;
            endcase
        end
    endfunction

    function automatic logic [NOTE_CODE_W-1:0] song_note(input logic [1:0] song, input int idx);
        begin
            unique case (song)
                SONG_WIN:  song_note = win_note(idx);
                SONG_FAIL: song_note = fail_note(idx);
                default:   song_note = bg_note(idx);
            endcase
        end
    endfunction

    function automatic logic [3:0] song_units(input logic [1:0] song, input int idx);
        begin
            unique case (song)
                SONG_WIN:  song_units = win_units(idx);
                SONG_FAIL: song_units = fail_units(idx);
                default:   song_units = bg_units(idx);
            endcase
        end
    endfunction

    task automatic load_note(input logic [1:0] song, input int idx);
        begin
            current_note  <= song_note(song, idx);
            current_units <= song_units(song, idx);
            duration_cnt  <= '0;
            tone_cnt      <= '0;
            beep_raw      <= 1'b0;
        end
    endtask

    always_ff @(posedge clk_i) begin
        if (rst_i) begin
            busy_o <= 1'b0;
            done_o <= 1'b0;
            beep_raw <= 1'b0;
            play_mode <= MODE_IDLE;
            active_song <= SONG_BACKGROUND;
            active_loop <= 1'b0;
            resume_song_after_collision <= 1'b0;
            note_index <= '0;
            current_note <= NOTE_REST;
            current_units <= 4'd1;
            duration_cnt <= '0;
            tone_cnt <= '0;
            collision_cnt <= '0;
            collision_tone_cnt <= '0;
        end else begin
            done_o <= 1'b0;

            if (stop_i) begin
                busy_o <= 1'b0;
                beep_raw <= 1'b0;
                play_mode <= MODE_IDLE;
                active_song <= SONG_BACKGROUND;
                active_loop <= 1'b0;
                resume_song_after_collision <= 1'b0;
                note_index <= '0;
                current_note <= NOTE_REST;
                current_units <= 4'd1;
                duration_cnt <= '0;
                tone_cnt <= '0;
                collision_cnt <= '0;
                collision_tone_cnt <= '0;
            end else if (play_start_i) begin
                busy_o <= 1'b1;
                active_song <= play_song_i;
                active_loop <= play_loop_i;
                play_mode <= MODE_SONG;
                resume_song_after_collision <= 1'b0;
                note_index <= '0;
                load_note(play_song_i, 0);
            end else begin
                unique case (play_mode)
                    MODE_IDLE: begin
                        busy_o <= 1'b0;
                        beep_raw <= 1'b0;
                        if (collision_start_i) begin
                            busy_o <= 1'b1;
                            play_mode <= MODE_COLLISION;
                            collision_cnt <= '0;
                            collision_tone_cnt <= '0;
                        end
                    end

                    MODE_COLLISION: begin
                        if (collision_tone_cnt >= (COLLISION_HALF_CYCLES - 1)) begin
                            collision_tone_cnt <= '0;
                            beep_raw <= ~beep_raw;
                        end else begin
                            collision_tone_cnt <= collision_tone_cnt + 1'b1;
                        end

                        if (collision_cnt >= (COLLISION_CYCLES - 1)) begin
                            collision_cnt <= '0;
                            collision_tone_cnt <= '0;
                            beep_raw <= 1'b0;
                            if (resume_song_after_collision) begin
                                busy_o <= 1'b1;
                                play_mode <= MODE_SONG;
                            end else begin
                                busy_o <= 1'b0;
                                play_mode <= MODE_IDLE;
                            end
                            resume_song_after_collision <= 1'b0;
                        end else begin
                            collision_cnt <= collision_cnt + 1'b1;
                        end
                    end

                    MODE_SONG: begin
                        if (collision_start_i && (active_song == SONG_BACKGROUND)) begin
                            busy_o <= 1'b1;
                            beep_raw <= 1'b0;
                            play_mode <= MODE_COLLISION;
                            resume_song_after_collision <= 1'b1;
                            collision_cnt <= '0;
                            collision_tone_cnt <= '0;
                        end else begin
                            if ((current_note == NOTE_REST) || (duration_cnt >= sound_cycles(current_units))) begin
                                beep_raw <= 1'b0;
                                tone_cnt <= '0;
                            end else if (tone_cnt >= (half_cycles_for_note(current_note) - 1)) begin
                                tone_cnt <= '0;
                                beep_raw <= ~beep_raw;
                            end else begin
                                tone_cnt <= tone_cnt + 1'b1;
                            end

                            if (duration_cnt >= (duration_cycles(current_units) - 1)) begin
                                if (int'(note_index) == (song_len(active_song) - 1)) begin
                                    if (active_loop) begin
                                        note_index <= '0;
                                        load_note(active_song, 0);
                                    end else begin
                                        busy_o <= 1'b0;
                                        done_o <= 1'b1;
                                        beep_raw <= 1'b0;
                                        play_mode <= MODE_IDLE;
                                        note_index <= '0;
                                        current_note <= NOTE_REST;
                                        current_units <= 4'd1;
                                        duration_cnt <= '0;
                                        tone_cnt <= '0;
                                    end
                                end else begin
                                    note_index <= note_index + 1'b1;
                                    load_note(active_song, int'(note_index) + 1);
                                end
                            end else begin
                                duration_cnt <= duration_cnt + 1'b1;
                            end
                        end
                    end

                    default: begin
                        busy_o <= 1'b0;
                        beep_raw <= 1'b0;
                        play_mode <= MODE_IDLE;
                    end
                endcase
            end
        end
    end
endmodule
